const isChild=location.pathname.startsWith('/child'),title=document.querySelector('#title'),fields=document.querySelector('#fields'),error=document.querySelector('#error'),register=document.querySelector('#register');let signup=false;
function render(){title.textContent=isChild?'Войти к Аяну':signup?'Аккаунт учителя':'Вход для учителя';document.querySelector('#description').textContent=isChild?'Вставь код, который дал учитель. Почта и пароль не нужны.':'Материалы занятия, ученики и их результаты — в вашем кабинете.';fields.innerHTML=isChild?'<label for="code">Код приглашения</label><input id="code" name="code" required autocomplete="off">':(signup?'<label for="name">Как к вам обращаться</label><input id="name" name="name" required autocomplete="name">':'')+'<label for="email">Почта</label><input id="email" name="email" type="email" required autocomplete="email"><label for="password">Пароль · от 4 символов</label><input id="password" name="password" type="password" minlength="4" required autocomplete="'+(signup?'new-password':'current-password')+'">';register.hidden=isChild;register.textContent=signup?'Уже есть аккаунт — войти':'Создать аккаунт учителя';}
register.onclick=()=>{signup=!signup;render();};render();if(isChild&&location.hash){document.querySelector('#code').value=location.hash.slice(1);history.replaceState(null,'',location.pathname);}
document.querySelector('form').onsubmit=async e=>{e.preventDefault();error.textContent='';const button=document.querySelector('#submit');button.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));const r=await fetch(isChild?'/api/child/enter':'/api/auth/'+(signup?'sign-up/email':'sign-in/email'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await r.json();if(!r.ok)throw Error(isChild?result.error:signup?'Не удалось создать аккаунт. Проверьте почту и пароль.':'Не удалось войти. Проверьте почту и пароль.');location.assign(isChild?'/child':'/teacher');}catch(e){error.textContent=e.message;}finally{button.disabled=false;}};
